import {KEY,fresh,today,validate,answered,finish,sample,examPool} from '/core.mjs';
const $=s=>document.querySelector(s),e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pdf=p=>`https://www.dmv.virginia.gov/sites/default/files/forms/dmv39.pdf#page=${p}`;
const src=p=>`<a href="${pdf(p)}" target="_blank" rel="noopener">DMV · trang in ${p-2} ↗</a>`;
const letters='ABCD',letter=x=>letters[Number(x)-1]||x;
let data,state,storageError=false,toastTimer,search='',quizPage=0;
const main=$('#main');
function notice(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function write(next){try{if(storageError)throw Error('Cần khôi phục bản lưu trước.');const old=localStorage.getItem(KEY);if(old)localStorage.setItem(KEY+'-backup',old);localStorage.setItem(KEY,JSON.stringify(next));state=next;return true;}catch{notice('Chưa lưu được. Hãy xuất tiến độ để giữ kết quả và kiểm tra dung lượng trình duyệt.');return false;}}
const update=fn=>{const next=structuredClone(state);fn(next);return write(next);};
function download(value,name){const blob=new Blob([typeof value==='string'?value:JSON.stringify(value,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function nav(path){history.pushState({},'',path);quizPage=0;render();window.scrollTo(0,0);main.focus({preventScroll:true});}
const countRead=l=>(state.read[l.id]||[]).filter(i=>i<l.sections.length).length;
const eligible=()=>data.questions.filter(q=>q.audit.status==='verified');
const byId=id=>data.questions.find(q=>q.id===id),deepById=id=>data.deep.find(q=>q.id===id);
const allAttempts=()=>Object.values(state.answers).reduce((n,a)=>n+a.attempts,0);
const wrongIds=()=>Object.entries(state.answers).filter(([id,a])=>!a.last_correct&&byId(id)?.audit.status==='verified').map(([id])=>id);
const dueIds=()=>Object.entries(state.answers).filter(([id,a])=>a.due<=today()&&byId(id)?.audit.status==='verified').sort((a,b)=>Number(a[1].last_correct)-Number(b[1].last_correct)||a[1].due.localeCompare(b[1].due)).map(([id])=>id);
function button(text,action,extra=''){const light=extra.includes('class="pill light"');return `<button class="pill${light?' light':''}" data-action="${action}" ${extra.replace('class="pill light"','')}>${text}</button>`;}
function title(kicker,heading,desc){return `<div class="page-title"><p class="eyebrow">${kicker}</p><h1>${heading}</h1><p>${desc}</p></div>`;}
function englishToggle(body,source=false){return `<details class="english-toggle"><summary><span class="english-chip" aria-hidden="true">EN</span><span class="english-show">Xem nội dung tiếng Anh</span><span class="english-hide">Thu gọn tiếng Anh</span></summary><div class="english-content" lang="en"><p class="english-label">${source?'ORIGINAL DMV TEXT':'ENGLISH LEARNING EXPLANATION · TUTOR TRANSLATION'}</p>${body}</div></details>`;}
function englishParagraphs(text){return text.replace(/(?:\d+\s*\|\s*VIRGINIA DRIVER[’']S MANUAL|VIRGINIA DRIVER[’']S MANUAL\s*\|\s*\d+)/g,' ').replace(/Section\s+\d+:\s*(?:Safe Driving|Signals, Signs and Pavement Markings|Seat Belts, Air Bags and Child Safety Seats)/g,' ').replace(/-\s+(?=[a-z])/g,'-').split('\u0017').map((p,i)=>`<p${i?' class="english-bullet"':''}>${i?'• ':''}${e(p.trim())}</p>`).join('');}
function englishSource(section){return englishToggle(`${section.english.noteEn?`<p class="english-warning"><b>Source note:</b> ${e(section.english.noteEn)}</p>`:''}${section.english.blocks.map(b=>`<div class="english-block"><h3>${e(b.heading)}</h3>${englishParagraphs(b.text)}<a class="english-citation" href="${pdf(b.pdfPage)}" target="_blank" rel="noopener">Virginia DMV · printed page ${b.pdfPage-2} ↗</a></div>`).join('')}`,true);}
function vietnameseSource(section){return `${section.fullVi.noteVi?`<aside class="source-warning"><b>Lưu ý về nguồn:</b> ${e(section.fullVi.noteVi)}</aside>`:''}<div class="full-vietnamese">${section.fullVi.blocks.map((b,i)=>`<div class="vietnamese-block" data-source-block="${i}" lang="vi"><h3>${e(b.headingVi)}</h3>${b.paragraphs.map(p=>`<p${p.startsWith('• ')?' class="vietnamese-bullet"':''}>${e(p)}</p>`).join('')}</div>`).join('')}</div><details class="quick-summary"><summary>Ghi nhớ nhanh — bản tóm tắt</summary>${section.body.map(p=>`<p>${e(p)}</p>`).join('')}</details>`;}
function heroArt(){return `<div class="hero-art" aria-hidden="true"><svg viewBox="0 0 520 365" fill="none"><ellipse cx="265" cy="297" rx="180" ry="29" fill="#cfddba"/><path d="M-20 335C150 365 170 210 318 216S494 241 550 98" stroke="#bbcda1" stroke-width="95"/><path d="M-20 330C150 360 170 205 318 211S494 236 550 93" stroke="#fdfdf7" stroke-width="70"/><path d="M-20 330C150 360 170 205 318 211S494 236 550 93" stroke="#c7d4b6" stroke-width="2" stroke-dasharray="10 12"/><path d="M190 112L221 94L252 112V146L221 164L190 146Z" fill="#78935c"/><path d="M221 164V230" stroke="#9bad86" stroke-width="6"/><path d="M221 117v22m-8-10l8 10 8-10" stroke="#f7f8ee" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><g transform="translate(302 187) rotate(-7)"><rect width="67" height="34" rx="12" fill="#264c40"/><path d="M15 5h25l10 10H7Z" fill="#abc5a1"/><rect x="13" y="-4" width="12" height="5" rx="2" fill="#173d3b"/><rect x="13" y="33" width="12" height="5" rx="2" fill="#173d3b"/><path d="M57 9v6m0 7v5" stroke="#e6ecb4" stroke-width="4"/></g><path d="M110 210v-70m-17 42l17-17 18 10" stroke="#acc193" stroke-width="6"/><ellipse cx="111" cy="135" rx="23" ry="33" fill="#8daa71"/><path d="M417 162v-65m-15 42l16-17 15 12" stroke="#acc193" stroke-width="5"/><ellipse cx="417" cy="91" rx="20" ry="29" fill="#9bb880"/><circle cx="322" cy="82" r="22" fill="#eff4d4"/><path d="M318 82l4 4 7-9" stroke="#6d8a51" stroke-width="2"/></svg><span class="art-label top">Từng bài nhỏ. Hiểu thật chắc.</span><span class="art-label bottom">VIRGINIA, USA · YOUR NEXT CHAPTER</span></div>`;}
function hubLegacy(){return `<div class="wrap"><section class="hub-hero"><div><p class="eyebrow">PHT LEARNING HUB</p><h1>Học điều mình cần.<br><em>Làm tốt điều mình yêu.</em></h1><p>Một trang chủ chung cho các bộ học cá nhân: lái xe, tiếng Anh và điện ảnh. Mỗi khu có lộ trình riêng, tiến độ rõ ràng và cách học vừa đủ.</p></div><div class="hub-mark" aria-hidden="true">↗</div></section><div class="section-title"><h2>Chọn một hành trình</h2><span class="muted">Mở từng khu để bắt đầu</span></div><div class="hub-grid"><a class="hub-card driving" href="/driving/"><span class="hub-number">01</span><p class="eyebrow">THỰC HÀNH & AN TOÀN</p><h2>Học lái xe Virginia</h2><p>16 bài lý thuyết tiếng Việt, hình gốc DMV, thuật ngữ tiếng Anh, câu hỏi ôn thi và lưu tiến độ trên máy.</p><span class="hub-link">Vào bộ học lái xe ↗</span></a><a class="hub-card english" href="/english/"><span class="hub-number">02</span><p class="eyebrow">NGÔN NGỮ & GIAO TIẾP</p><h2>Học tiếng Anh</h2><p>Học theo tình huống thực tế: nghe, nói, từ vựng và mẫu câu dùng được trong công việc và đời sống.</p><span class="hub-link">Mở khu tiếng Anh ↗</span></a><a class="hub-card cinema" href="/cinema/"><span class="hub-number">03</span><p class="eyebrow">HÌNH ẢNH & KỂ CHUYỆN</p><h2>Cẩm nang điện ảnh</h2><p>Đọc hình ảnh, dựng cảnh, viết thoại và làm một bộ phim ngắn có chủ đích từ ý tưởng ban đầu.</p><span class="hub-link">Mở cẩm nang điện ảnh ↗</span></a></div><section class="hub-note"><p class="eyebrow">CÁCH DÙNG</p><h2>Mỗi khu là một căn phòng riêng.</h2><p>Bạn có thể quay lại bất kỳ lúc nào. Khu DMV tự lưu tiến độ; các khu mới bắt đầu bằng những bài ngắn, dễ mở rộng theo nhu cầu.</p></section></div>`;}
function hub(){return `<div class="hub-wrap"><section class="hub-hero hub-hero-new"><div class="hub-hero-copy"><p class="hub-kicker">PHT / LEARNING HUB</p><h1>Mở một cánh cửa.<br><em>Đi xa hơn mỗi ngày.</em></h1><p>Một không gian học tập riêng cho những điều bạn đang xây: tự tin lái xe, giao tiếp bằng tiếng Anh, kể chuyện bằng hình ảnh và sáng tác âm nhạc.</p><div class="hub-actions"><a class="hub-primary" href="/driving/">Bắt đầu học ngay <span>↗</span></a><span class="hub-quiet">7 phòng học · học theo nhịp của bạn</span></div></div><div class="hub-visual" aria-hidden="true"><div class="orbit orbit-a"></div><div class="orbit orbit-b"></div><div class="hub-spark spark-a">✦</div><div class="hub-spark spark-b">·</div><div class="hub-note-card"><b>HÔM NAY</b><span>một bước nhỏ<br>cũng là tiến bộ</span><strong>01</strong></div><div class="hub-circle">pht</div></div></section><div class="hub-section-heading"><div><p class="hub-kicker">CHỌN PHÒNG HỌC</p><h2>Điều gì đang gọi bạn?</h2></div><p>Mở một lộ trình và bắt đầu từ bài đầu tiên.</p></div><div class="hub-grid hub-grid-new"><div class="hub-card english"><div class="hub-card-top"><span class="hub-number">01</span><span class="hub-symbol">Aa</span></div><p class="hub-kicker">NGÔN NGỮ &amp; GIAO TIẾP</p><h2>Học<br/><em>tiếng Anh</em></h2><p>Từ vựng, mẫu câu và phản xạ cho công việc, đời sống và những cuộc trò chuyện thật.</p><a class="hub-link" href="https://ptoan-pq.github.io/pq-buddhist-english/" rel="noopener" target="_blank">Mở website tiếng Anh <b>→</b></a><a class="hub-repo" href="https://github.com/ptoan-pq/pq-buddhist-english" rel="noopener" target="_blank">Repo GitHub ↗</a></div><a class="hub-card nikaya" href="https://ptoan-pq.github.io/thu-vien-nikaya/"><div class="hub-card-top"><span class="hub-number">02</span><span aria-hidden="true" class="hub-symbol">☸</span></div><p class="hub-kicker">KINH ĐIỂN &amp; QUÁN CHIẾU</p><h2>Thư viện<br/><em>Nikāya</em></h2><p>Tra cứu theo tên và mã kinh. Đọc tóm lược có bố cục, phân tích ẩn dụ và bài học ứng dụng; nguyên văn dẫn về BuddhaSasana.</p><span class="hub-link">Mở thư viện Nikāya <b>→</b></span></a><div class="hub-card cinema"><div class="hub-card-top"><span class="hub-number">03</span><span class="hub-symbol">●</span></div><p class="hub-kicker">HÌNH ẢNH &amp; KỂ CHUYỆN</p><h2>Cẩm nang<br/><em>điện ảnh</em></h2><p>Ngôn ngữ hình ảnh, cấu trúc cảnh và bài tập biến một ý tưởng thành shot list.</p><a class="hub-link" href="https://ptoan-pq.github.io/cam-nang-dien-anh/" rel="noopener" target="_blank">Mở cẩm nang điện ảnh <b>→</b></a><a class="hub-repo" href="https://github.com/ptoan-pq/thu-vien-ky-thuat-dien-anh" rel="noopener" target="_blank">Kho kỹ thuật trên GitHub ↗</a></div><a class="hub-card driving" href="/driving/"><div class="hub-card-top"><span class="hub-number">04</span><span class="hub-symbol">↗</span></div><p class="hub-kicker">THỰC HÀNH &amp; AN TOÀN</p><h2>Học lái xe<br/><em>Virginia</em></h2><p>16 bài học có hình, câu hỏi DMV bằng tiếng Anh và tiến độ lưu ngay trên máy.</p><span class="hub-link">Vào bộ học lái xe <b>→</b></span></a><a class="hub-card music" data-document="" href="/music/"><div class="hub-card-top"><span class="hub-number">05</span><span aria-hidden="true" class="hub-symbol">♫</span></div><p class="hub-kicker">ÂM NHẠC &amp; SÁNG TÁC</p><h2>Học viết nhạc<br/><em>bằng tai</em></h2><p>40 nguyên tắc viết nhạc, 8 bản âm thanh và các mẫu nghe so sánh để hiểu giai điệu, hòa âm, nhịp và cách phối.</p><span class="hub-link">Mở phòng học nhạc <b>→</b></span></a><div class="hub-card american-english"><div class="hub-card-top"><span class="hub-number">06</span><span aria-hidden="true" class="hub-symbol">EN</span></div><p class="hub-kicker">TIẾNG ANH &amp; VĂN HÓA HOA KỲ</p><h2>Sống Mỹ<br/><em>tự tin mỗi ngày</em></h2><p>43 chủ đề đời sống, 195 đoạn có bản dịch tiếng Việt và 645 câu luyện tập tương tác. Bấm đoạn để dịch, chọn từ để điền và sửa các ô sai.</p><a class="hub-link" href="https://ptoan-pq.github.io/song-my-english-campus/" rel="noopener" target="_blank">Mở website Sống Mỹ <b>→</b></a><a class="hub-repo" href="https://github.com/ptoan-pq/song-my-english-campus" rel="noopener" target="_blank">Repo GitHub ↗</a></div><div class="hub-card memorize"><div class="hub-card-top"><span class="hub-number">07</span><span aria-hidden="true" class="hub-symbol">✓</span></div><p class="hub-kicker">GHI NHỚ &amp; ÔN TẬP</p><h2>Thuộc Lòng<br/><em>từng cụm một</em></h2><p>Học thuộc kinh, thơ và lời thoại theo 5 bước: che dần, chữ đầu, điền từ, kèm lịch ôn tự động. Bấm vào khoảng trắng để mở lần lượt từng ô.</p><a class="hub-link" href="https://ptoan-pq.github.io/thuoc-long/" rel="noopener" target="_blank">Mở Thuộc Lòng <b>→</b></a><a class="hub-repo" href="https://github.com/ptoan-pq/thuoc-long" rel="noopener" target="_blank">Repo GitHub ↗</a></div></div><section class="hub-bottom"><span class="hub-bottom-mark">✳</span><p><b>Không cần học hết trong một ngày.</b> Chọn một bài, làm thật chắc, rồi quay lại khi bạn sẵn sàng cho bước tiếp theo.</p><a href="/driving/">Xem lộ trình DMV ↗</a></section></div>`;}
function english(){return `<div class="wrap">${title('KHU HỌC TIẾNG ANH','Tiếng Anh dùng được trong đời sống.','Bắt đầu bằng câu ngắn, tình huống thật và những lần lặp lại có chủ đích.')}<div class="topic-list"><article class="panel"><p class="eyebrow">01 · NỀN TẢNG</p><h2>Từ vựng theo tình huống</h2><p>Nhóm từ theo nơi bạn gặp chúng: công việc, mua sắm, đi khám, gọi điện và giao tiếp hằng ngày.</p><a class="pill" href="/english/#vocabulary">Xem lộ trình ↗</a></article><article class="panel"><p class="eyebrow">02 · PHẢN XẠ</p><h2>Mẫu câu nói ngay</h2><p>Học một mẫu câu, thay đổi một chi tiết, rồi tự nói lại bằng thông tin của mình.</p><a class="pill light" href="/english/#speaking">Xem bài nói ↗</a></article><article class="panel"><p class="eyebrow">03 · HIỂU SÂU</p><h2>Nghe và đoán ý</h2><p>Luyện nhận ra từ khóa, ý chính và sắc thái thay vì cố dịch từng chữ.</p><a class="pill light" href="/english/#listening">Xem cách luyện ↗</a></article></div><section class="theory-section" id="vocabulary"><p class="eyebrow">START SMALL</p><h2>Một buổi học 15 phút</h2><ol><li>Chọn 5 từ gắn với việc bạn sẽ làm hôm nay.</li><li>Viết một câu ngắn cho mỗi từ.</li><li>Đọc thành tiếng ba lần, rồi dùng lại trong một tình huống khác.</li></ol></section><section class="theory-section" id="speaking"><p class="eyebrow">SPEAKING</p><h2>Khung câu để bắt đầu</h2><div class="term-list"><div class="term"><b>Could you help me with…?</b><small>Bạn có thể giúp tôi về…?</small><p>Dùng khi cần nhờ giúp đỡ một cách lịch sự.</p></div><div class="term"><b>I’m not sure I understand.</b><small>Tôi chưa chắc mình hiểu.</small><p>Dùng để xin người đối thoại giải thích lại.</p></div><div class="term"><b>Let me check and get back to you.</b><small>Để tôi kiểm tra rồi trả lời lại.</small><p>Dùng khi bạn cần thêm thời gian.</p></div></div></section><section class="theory-section" id="listening"><p class="eyebrow">LISTENING</p><h2>Nghe để bắt ý chính</h2><p>Nghe lần đầu để biết chủ đề. Lần thứ hai ghi lại từ khóa. Lần thứ ba nói lại ý chính bằng câu của bạn. Chưa cần hiểu từng chữ mới được xem là học đúng.</p></section></div>`;}
function cinema(){return `<div class="wrap">${title('CẨM NANG ĐIỆN ẢNH','Nhìn một cảnh. Hiểu một câu chuyện.','Một lộ trình gọn để học ngôn ngữ hình ảnh, cấu trúc cảnh và cách đưa ý tưởng lên màn hình.')}<div class="topic-list"><article class="panel"><p class="eyebrow">01 · NGÔN NGỮ HÌNH ẢNH</p><h2>Khung hình có chủ ý</h2><p>Cỡ cảnh, góc máy, ánh sáng và khoảng trống đều trả lời một câu hỏi: khán giả cần cảm thấy điều gì ngay lúc này?</p><a class="pill" href="/cinema/#visual-language">Đọc phần này ↗</a></article><article class="panel"><p class="eyebrow">02 · CẤU TRÚC CẢNH</p><h2>Mục tiêu, cản trở, thay đổi</h2><p>Một cảnh tốt không chỉ truyền thông tin. Nhân vật bước vào với một mong muốn và bước ra với một điều đã khác.</p><a class="pill light" href="/cinema/#scene">Đọc phần này ↗</a></article><article class="panel"><p class="eyebrow">03 · THỰC HÀNH</p><h2>Từ ý tưởng đến shot list</h2><p>Viết logline, chia cảnh, chọn khung hình chủ đạo rồi mới tính thiết bị và lịch quay.</p><a class="pill light" href="/cinema/#practice">Đọc phần này ↗</a></article></div><section class="theory-section" id="visual-language"><p class="eyebrow">VISUAL LANGUAGE</p><h2>Ba câu hỏi trước khi đặt máy</h2><ul><li>Ai là người nhìn và khán giả đang đứng ở đâu?</li><li>Điều gì trong khung hình cần được chú ý trước tiên?</li><li>Chuyển động của máy đang kể thêm điều gì?</li></ul></section><section class="theory-section" id="scene"><p class="eyebrow">SCENE DESIGN</p><h2>Một cảnh có nhịp thay đổi</h2><p>Hãy xác định điều nhân vật muốn, điều ngăn họ lại và khoảnh khắc khiến cách nhìn của họ thay đổi. Nếu không có thay đổi, cảnh có thể chỉ là phần giải thích kéo dài.</p></section><section class="theory-section" id="practice"><p class="eyebrow">PRACTICE</p><h2>Bài tập 10 phút</h2><ol><li>Viết một logline trong một câu.</li><li>Chọn một địa điểm và một vật thể quan trọng.</li><li>Viết 5 shot theo thứ tự nhìn thấy.</li><li>Ghi âm một câu thoại duy nhất làm thay đổi ý nghĩa cảnh.</li></ol></section></div>`;}
function home(){const lesson=data.lessons.find(l=>l.id===state.current)||data.lessons[0],wrong=wrongIds().length,attempts=allAttempts(),correct=Object.values(state.answers).reduce((n,a)=>n+a.correct,0);return `<div class="wrap"><div class="intro-line"><p class="eyebrow" style="margin:0">SỔ TAY LÁI XE CỦA BẠN</p><span class="status-dot">Lưu trên thiết bị này</span></div><section class="hero"><div class="hero-copy"><p class="eyebrow">HIỂU LUẬT. VỮNG TAY LÁI.</p><h1>Con đường đến<br>tấm bằng lái <em>Virginia.</em></h1><p>Học từng chút bằng tiếng Việt, nhìn hình gốc DMV và hiểu cách áp dụng trên đường. Mỗi lần quay lại, tiếp tục từ nơi bạn đã dừng.</p><div class="button-row"><a class="pill" href="/lessons/${lesson.id}/">${attempts||countRead(lesson)?'Tiếp tục học':'Bắt đầu bài đầu tiên'} <span class="arrow">↗</span></a><a class="pill light" href="/lessons/">Khám phá 16 bài học</a></div></div>${heroArt()}</section><div class="stats"><div class="stat"><strong>16</strong><span>bài học có hình</span></div><div class="stat"><strong>${eligible().length}</strong><span>câu DMV dùng để ôn</span></div><div class="stat"><strong>${data.deep.length}</strong><span>bài tập hiểu sâu</span></div><div class="stat"><strong>${attempts?Math.round(correct/attempts*100)+'%':'—'}</strong><span>${attempts?'đúng qua '+attempts+' lượt':'sẵn sàng bắt đầu'}</span></div></div><div class="home-grid"><div><div class="section-title"><h2>Bước tiếp theo của bạn</h2><a href="/progress/">Xem tiến độ ↗</a></div><article class="continue"><div class="lesson-illustration">${lesson.id.slice(1)}</div><div><p class="eyebrow">BÀI ${Number(lesson.id.slice(1))} / 16</p><h3>${e(lesson.title)}</h3><p>${state.active?'Gói câu hỏi đang làm đã được lưu.':state.checkpoint?e(state.checkpoint):'Bắt đầu từ quy tắc, hiểu qua hình ảnh.'}</p><div class="progress-line"><span style="width:${countRead(lesson)/lesson.sections.length*100}%"></span></div><p>${countRead(lesson)}/${lesson.sections.length} mục lý thuyết đã đánh dấu</p></div><a class="pill white" href="${state.active?state.active.mode==='deep'?'/deep/':'/practice/':`/lessons/${lesson.id}/`}">Mở tiếp ↗</a></article><div class="two-cards"><article class="mode-card"><span class="tag">CÂU HỎI GỐC</span><div class="mode-icon" aria-hidden="true">☷</div><h3>Ôn thi cùng DMV</h3><p>Luyện gói 5–10 câu, ôn câu sai hoặc làm đề mô phỏng hai phần.</p><a href="/practice/">Vào khu ôn thi ↗</a></article><article class="mode-card deep"><span class="tag">VẬN DỤNG & LẬP LUẬN</span><div class="mode-icon" aria-hidden="true">✳</div><h3>Hiểu sâu từng quy tắc</h3><p>Tình huống thay đổi một chi tiết. Bạn có còn đưa ra quyết định đúng?</p><a href="/deep/">Thử sức với bài khó ↗</a></article></div></div><aside class="home-aside"><article class="side-note"><p class="eyebrow">NHỚ KỸ HƠN MỖI NGÀY</p><h3>${dueIds().length?'Đến lúc ôn lại':'Một chút mỗi ngày'}</h3><p>${dueIds().length?`${dueIds().length} câu đã đến lịch ôn, trong đó ${wrong} câu gần nhất còn sai.`:'Đọc một phần lý thuyết, làm một gói nhỏ, rồi xem lại vì sao mình chọn đáp án đó.'}</p>${dueIds().length?button('Ôn câu đến hạn ↗','start-due'):''}</article><article class="side-note"><h3>Nguồn rõ ràng.<br>Học có căn cứ.</h3><p>Lý thuyết và hình từ sổ tay Virginia DMV. Bài tập hiểu sâu có nhãn riêng và dẫn trang quy tắc.</p><div class="source-stamp"><span class="stamp">DMV</span><span>BẢN THÁNG 4/2026<br><a href="/sources/">Xem nguồn & lưu ý ↗</a></span></div></article></aside></div></div>`;}
function lessons(){return `<div class="wrap">${title('LỘ TRÌNH 16 BÀI','Từng bài nhỏ, nền tảng vững.','Học theo thứ tự hoặc mở lại phần cần ôn. Mỗi bài có lý thuyết tiếng Việt, hình gốc, thuật ngữ thực tế và chỗ dễ nhầm.')}<div class="filters"><label>Tìm bài học<input id="lesson-search" type="search" placeholder="Ví dụ: đèn đỏ, nhường đường, điểm mù…" value="${e(search)}"></label></div><div class="lesson-grid" id="lesson-list">${lessonCards()}</div></div>`;}
function lessonCards(){const list=data.lessons.filter(l=>(l.title+' '+l.intro+' '+l.terms.map(t=>t.en+' '+t.vi).join(' ')).normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase().includes(search.normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase()));return list.length?list.map(l=>`<a class="lesson-card" href="/lessons/${l.id}/"><span class="number">BÀI ${l.id.slice(1)} <span class="badge">${countRead(l)===l.sections.length?'Đã đọc':countRead(l)?'Đang học':'Tự học'}</span></span><h3>${e(l.title)}</h3><div class="progress-line"><span style="width:${countRead(l)/l.sections.length*100}%"></span></div><span class="card-bottom"><span>${l.sections.length} mục · ${data.questions.filter(q=>q.lesson===l.id&&q.audit.status==='verified').length} câu DMV</span><span>↗</span></span></a>`).join(''):'<p class="muted">Chưa tìm thấy bài phù hợp. Thử từ khóa khác.</p>';}
function lessonPool(id,kind){
 const pool=eligible().filter(q=>kind==='practice'?q.lesson===id:q.lesson<id&&(state.answers[q.id]||(state.read[q.lesson]||[]).length));
 const rank=q=>!state.answers[q.id]?1:state.answers[q.id].last_correct?2:0;
 return pool.sort((a,b)=>rank(a)-rank(b)||(state.answers[a.id]?.due||'').localeCompare(state.answers[b.id]?.due||''));
}
function lessonBatch(id,kind,size){
 const pool=lessonPool(id,kind);if(!pool.length)return null;
 return {token:crypto.randomUUID(),mode:'official',lesson:id,...(kind==='review'?{reviewFor:id}:{}),ids:pool.slice(0,size).map(q=>q.id),choices:{},created:new Date().toISOString()};
}
function prepareLessonSessions(id){
 if(!data.lessons.some(l=>l.id===id))return;
 const next=structuredClone(state);let changed=false;
 for(const kind of ['review','practice']){
  const slot=id+':'+kind;if(next.lessonSessions[slot])continue;
  const active=kind==='review'&&!state.reviewed[id]||kind==='practice'?lessonBatch(id,kind,5):null;
  if(!active)continue;
  next.lessonSessions[slot]={active,last:null,size:5};changed=true;
 }
 if(changed)write(next);
}
function lessonQuiz(id,kind){
 const slot=id+':'+kind,session=state.lessonSessions[slot],review=kind==='review';
 const heading=review?'Ôn bài cũ trước khi học tiếp':'Kiểm tra ngay bài vừa học';
 const description=review?'Một gói ngắn từ các bài trước bạn đã học. Ưu tiên câu sai, sau đó là câu chưa làm và câu lâu chưa ôn.':'Trả lời ngay bên dưới, chấm cả gói rồi xem lại đáp án và giải thích.';
 return `<section class="lesson-quiz" id="lesson-${kind}" aria-labelledby="heading-${kind}"><p class="eyebrow">${review?'TRƯỚC BÀI HỌC':'SAU BÀI HỌC'}</p><h2 id="heading-${kind}">${heading}</h2><p class="muted">${description}</p>${session?.active?activeQuiz(session,slot):session?.last?`<details class="lesson-results"><summary lang="en">Results saved · ${session.last.score}/${session.last.total} · View answers and explanations</summary>${resultsPage(session,slot)}</details>${review?'<a class="pill light" href="#section-0" data-scroll="section-0">Continue to the lesson ↓</a>':lessonNext(slot,session.size)}`:review?`<div class="callout">${state.reviewed[id]?'Bạn đã hoàn thành phần ôn bài cũ của bài này.':'Chưa có bài trước đã học để ôn. Các bài tiếp theo sẽ có câu kiểm tra ở đây sau khi bạn học hoặc trả lời câu hỏi ở bài trước.'}</div>`:'<div class="callout">Bài này chưa có câu DMV đủ căn cứ để chấm. Bạn có thể làm bài tập hiểu sâu bên dưới.</div>'}</section>`;
}
function lessonNext(slot,size){return `<div class="filters" lang="en" data-quiz-slot="${e(slot)}"><label>Next set size<select data-lesson-size><option value="5" ${size===5?'selected':''}>5 questions</option><option value="10" ${size===10?'selected':''}>10 questions</option></select></label>${button('Start next practice set →','lesson-next')}</div>`;}
function quizSession(el){const slot=el.closest('[data-quiz-slot]')?.dataset.quizSlot;return {slot,session:slot?state.lessonSessions[slot]:state};}
function scrollQuiz(slot){if(slot)document.getElementById('lesson-'+slot.split(':')[1])?.scrollIntoView({block:'start'});else window.scrollTo(0,0);}
function lessonPage(id){const l=data.lessons.find(x=>x.id===id);if(!l)return notFound();return `<div class="wrap"><div class="lesson-layout"><aside class="lesson-sidebar"><p class="eyebrow">LỘ TRÌNH CỦA BẠN</p>${data.lessons.map(x=>`<a href="/lessons/${x.id}/" ${x.id===id?'class="active" aria-current="page"':''}><span>${x.id.slice(1)}</span>${e(x.title)}</a>`).join('')}</aside><article><p class="eyebrow">BÀI ${Number(id.slice(1))} / 16 · HỌC LÝ THUYẾT</p><div class="lesson-heading"><h1>${e(l.title)}</h1></div><p class="muted" style="font-size:13px">${e(l.intro)}</p><div class="lesson-meta"><span>${l.sections.length} mục lý thuyết</span><span>${countRead(l)} mục đã đánh dấu</span><span>PDF trang in ${l.pdf_pages[0]-2}–${Math.min(37,l.pdf_pages.at(-1))-2}</span></div>${lessonQuiz(id,'review')}${l.sections.map((s,i)=>`<section class="theory-section" id="section-${i}"><p class="eyebrow">${String(i+1).padStart(2,'0')} · QUY TẮC TRONG THỰC TẾ</p><h2>${e(s.title)}</h2>${s.image?`<img class="rule-image" src="/${e(s.image)}" alt="Hình DMV: ${e(s.title)}" loading="lazy">`:`<button class="page-thumb inline-page" data-action="zoom" data-page="${s.pdfPage}" aria-label="Phóng trang gốc cho phần ${e(s.title)}"><img src="/assets/visuals/page-${String(s.pdfPage).padStart(2,'0')}.png" alt="Trang DMV gốc cho phần ${e(s.title)}" loading="lazy">Hình trang gốc · nhấn để phóng lớn</button>`}${vietnameseSource(s)}${englishSource(s)}<div class="section-end">${src(s.pdfPage)}<button class="read-button" data-action="read" data-lesson="${id}" data-index="${i}" aria-pressed="${(state.read[id]||[]).includes(i)}">${(state.read[id]||[]).includes(i)?'✓ Đã đọc phần này':'Đánh dấu đã đọc'}</button></div></section>`).join('')}<section class="theory-section"><p class="eyebrow">GIỮ TỪ TIẾNG ANH, HIỂU BẰNG THỰC TẾ</p><h2>Thuật ngữ cần nhớ</h2><div class="term-list">${l.terms.map(t=>`<div class="term"><b>${e(t.en)}</b><small>${e(t.vi)}</small><p>${e(t.example)}</p>${englishToggle(`<p>${e(t.exampleEn)}</p>`)}<small>${src(t.pdfPage)}</small></div>`).join('')}</div></section><section class="theory-section"><h2>Chỗ dễ nhầm</h2>${l.pitfalls.map(p=>`<div class="pitfall"><p><b>Cách hiểu dễ nhầm:</b> ${e(p.wrong)}</p><p><b>Hiểu đúng:</b> ${e(p.right)}</p>${englishToggle(`<p><b>Possible misunderstanding:</b> ${e(p.wrongEn)}</p><p><b>Correct understanding:</b> ${e(p.rightEn)}</p>`)}<small>${src(p.pdfPage)}</small></div>`).join('')}</section><section class="theory-section"><h2>Nhìn lại trang DMV gốc</h2><p>Nhấn ảnh để phóng lớn. Bản tiếng Việt là diễn giải hỗ trợ học; xem đầy đủ điều kiện trong trang gốc.</p><div class="source-pages">${l.pdf_pages.filter(p=>p<38).map(p=>`<button class="page-thumb" data-action="zoom" data-page="${p}" aria-label="Phóng lớn trang in ${p-2}"><img src="/assets/visuals/page-${String(p).padStart(2,'0')}.png" alt="Nguyên trang in ${p-2} của sổ tay DMV" loading="lazy">Trang in ${p-2}</button>`).join('')}</div></section><section class="theory-section"><h2>Ghi chú của bạn</h2><label for="lesson-note" class="form-note">Tự viết lại điều cần nhớ (tự lưu trên trình duyệt).</label><textarea class="notes" id="lesson-note" data-lesson="${id}" maxlength="20000" placeholder="Ví dụ: phân biệt đèn đỏ tròn và mũi tên đỏ…">${e(state.notes[id]||'')}</textarea><p class="form-note" id="notes-status">${state.notes[id]?'Đã lưu ghi chú.':''}</p></section>${lessonQuiz(id,'practice')}<div class="button-row"><a class="pill light" href="/practice/?lesson=${id}">Mở khu ôn thi riêng ↗</a><a class="pill light" href="/deep/?lesson=${id}">Kiểm tra hiểu sâu ↗</a>${Number(id.slice(1))<16?`<a class="pill light" href="/lessons/L${String(Number(id.slice(1))+1).padStart(2,'0')}/">Bài tiếp theo →</a>`:''}</div><p class="form-note">“Đã đọc” ghi nhận bạn đã xem phần học; kết quả luyện tập hiển thị riêng trong Tiến độ.</p></article></div></div>`;}
function selectors(mode){const selected=new URLSearchParams(location.search).get('lesson')||'all';return `<div class="filters"><label>Chủ đề<select id="topic"><option value="all">Tất cả bài học</option>${data.lessons.map(l=>`<option value="${l.id}" ${selected===l.id?'selected':''}>${l.id.slice(1)} · ${e(l.title)}</option>`).join('')}</select></label><label>Số câu mỗi gói<select id="size"><option value="5">5 câu</option><option value="10">10 câu</option></select></label>${mode==='official'?'<label>Chọn câu<select id="selection"><option value="new">Chưa làm → câu sai</option><option value="wrong">Chỉ câu gần nhất sai</option><option value="due">Đến lịch ôn</option><option value="random">Ngẫu nhiên</option></select></label>':''}${button(mode==='deep'?'Bắt đầu bài tập ↗':'Bắt đầu gói câu hỏi ↗','start-'+mode)}</div>`;}
function quizLanding(mode){const deep=mode==='deep';return `<div class="wrap">${title(deep?'HIỂU SÂU · CÂU HỎI DO GIA SƯ BIÊN SOẠN':'ÔN THI · NGÂN HÀNG CÂU HỎI GỐC',deep?'Hiểu được vì sao.':'Luyện chắc từng câu DMV.',deep?'Thay đổi điều kiện, tìm đủ các bước đúng và giải thích quyết định. Quy tắc lấy từ DMV; tình huống và bài tập do gia sư biên soạn, tách riêng kết quả ôn thi.':'Câu hỏi và lựa chọn giữ nguyên tiếng Anh từ Study Guide. Phần trả lời và giải thích cũng chỉ hiển thị tiếng Anh.')}<div class="callout ${deep?'warning':''}">${deep?'Bài chọn nhiều đáp án cần chọn đủ và đúng. Bài tự luận có đáp án mẫu và tiêu chí tự đối chiếu; website không tự chấm ý nghĩa câu viết.':`${eligible().length} câu đã đối chiếu được dùng để chấm. ${data.questions.length-eligible().length} câu đang giữ để rà lại, xem lý do ở trang Nguồn.`}</div>${activeBanner(mode)}${selectors(mode)}${deep?`<div class="lesson-grid">${data.lessons.map(l=>`<a class="lesson-card" href="/deep/?lesson=${l.id}"><span class="number">BÀI ${l.id.slice(1)} <span class="badge">${data.deep.filter(q=>q.lesson===l.id).length} bài tập</span></span><h3>${e(l.title)}</h3><span class="card-bottom">Tình huống · Chọn nhiều · Tự luận <span>↗</span></span></a>`).join('')}</div>`:`<div class="review-grid"><article class="panel"><p class="eyebrow">MÔ PHỎNG CẤU TRÚC HAI PHẦN</p><h2>Một lần làm đề hoàn chỉnh.</h2><p>Phần 1: 10 câu biển báo, cần đúng cả 10. Nếu đạt, mở phần 2: 30 câu kiến thức chung, cần đúng ít nhất 24. Mỗi trang hiển thị 10 câu, lựa chọn lưu ngay.</p><p>Đề luyện lấy từ ngân hàng công khai, không phải bộ câu hỏi thi thật. Chế độ này không giới hạn thời gian.</p>${button('Làm đề mô phỏng ↗','start-exam')}</article><article class="panel"><p class="eyebrow">ÔN THEO TIẾN ĐỘ</p><h2>${wrongIds().length} câu cần sửa.</h2><p>${dueIds().length} câu đã đến ngày ôn. Câu đúng được hẹn sau 1, 3, 7, 14 ngày theo chuỗi đúng; câu sai cần ôn sớm.</p><div class="practice-actions">${button('Ôn câu đến hạn','start-due')}${button('Ôn câu sai','start-wrong','class="pill light"')}</div><p class="form-note">Lịch ôn là cách học của bộ học, không phải quy định DMV.</p></article></div>`}</div>`;}
function activeBanner(mode){if(!state.active)return '';const a=state.active;return `<div class="callout">Bạn có một gói ${a.mode==='deep'?'hiểu sâu':a.mode==='exam'?'mô phỏng':'DMV'} đang làm. Lựa chọn đã được lưu. <a class="text-button" href="${a.mode==='deep'?'/deep/':'/practice/'}">Tiếp tục gói đang làm ↗</a></div>`;}
function start(mode,special){if(state.active){notice('Tiếp tục gói đang làm trước; có thể xuất tiến độ để sao lưu.');nav(state.active.mode==='deep'?'/deep/':'/practice/');return;}
 const topic=$('#topic')?.value||'all',size=Number($('#size')?.value||5);let pool=mode==='deep'?data.deep:eligible();if(topic!=='all'&&!special)pool=pool.filter(q=>q.lesson===topic);
 if(mode==='official'){const sel=special||$('#selection')?.value||'new';if(sel==='wrong')pool=pool.filter(q=>wrongIds().includes(q.id));else if(sel==='due')pool=pool.filter(q=>dueIds().includes(q.id));else if(sel==='random')pool=sample(pool,pool.length);else{const unseen=pool.filter(q=>!state.answers[q.id]),wrong=pool.filter(q=>state.answers[q.id]&&!state.answers[q.id].last_correct);pool=unseen.length||wrong.length?[...unseen,...wrong]:sample(pool,pool.length);}if(sel==='due')pool.sort((a,b)=>dueIds().indexOf(a.id)-dueIds().indexOf(b.id));}
 else{const todo=pool.filter(q=>!state.deep[q.id]||state.deep[q.id].correct===false);pool=sample(todo.length?todo:pool,pool.length);}
 if(!pool.length){notice('Chưa có câu phù hợp với lựa chọn này. Hãy chọn chủ đề hoặc kiểu ôn khác.');return;}
 if(update(s=>{s.active={token:crypto.randomUUID(),mode,lesson:topic,ids:pool.slice(0,size).map(q=>q.id),choices:{},created:new Date().toISOString()};s.last=null;})){nav(mode==='deep'?'/deep/':'/practice/');}
}
function startExam(){if(state.active){notice('Hãy tiếp tục gói đang làm trước.');nav(state.active.mode==='deep'?'/deep/':'/practice/');return;}const p=examPool(data.questions);if(p.signs.length<10||p.general.length<30){notice('Ngân hàng chưa đủ câu đã đối chiếu để tạo đề.');return;}if(update(s=>{s.active={token:crypto.randomUUID(),mode:'exam',stage:'signs',ids:sample(p.signs,10).map(q=>q.id),general:sample(p.general,30).map(q=>q.id),choices:{},created:new Date().toISOString()};s.last=null;}))nav('/practice/');}
function activeQuiz(session=state,slot=null){const a=session.active,isDeep=a.mode==='deep',pool=isDeep?data.deep:data.questions,per=10,pages=Math.ceil(a.ids.length/per);const page=slot?0:Math.min(quizPage,pages-1);if(!slot)quizPage=page;const chosen=a.ids.filter(id=>answered(pool.find(q=>q.id===id),a.choices[id],a.mode)).length;const label=slot?.endsWith(':review')?'Review previous lessons':isDeep?'Deep practice':a.mode==='exam'?`Practice exam · ${a.stage==='signs'?'Part 1: traffic signs':'Part 2: general knowledge'}`:'DMV practice questions';return `${slot?'':'<div class="wrap">'}<div class="quiz-shell" lang="en" ${slot?`data-quiz-slot="${e(slot)}"`:''}><p class="eyebrow">${isDeep?'TUTOR-WRITTEN EXERCISES · DMV SOURCES':'ORIGINAL DMV STUDY GUIDE QUESTIONS'}</p><div class="quiz-toolbar"><${slot?'h3':'h1'} style="font-size:32px;margin:0">${label}</${slot?'h3':'h1'}><span class="status-dot">Answers saved automatically</span></div><p class="muted" style="font-size:12px">${isDeep?'Read every condition carefully. Multiple-answer questions may have more than one correct answer.':'Answer the whole set, then submit it for grading. DMV answer choices remain in their original order.'}</p>${a.ids.length<5?'<div class="callout">This topic has only '+a.ids.length+' matching questions remaining, so this final set has fewer than 5 questions.</div>':''}${a.ids.slice(page*per,(page+1)*per).map((id,i)=>questionCard(pool.find(q=>q.id===id),page*per+i+1,a)).join('')}${pages>1?`<div class="quiz-toolbar"><button class="pill light" data-action="page-prev" ${quizPage===0?'disabled':''}>← Previous</button><span>Page ${quizPage+1}/${pages}</span><button class="pill light" data-action="page-next" ${quizPage===pages-1?'disabled':''}>Next →</button></div>`:''}<div class="quiz-submit"><p ${slot?'':'id="chosen-count"'} data-quiz-count>Answered ${chosen}/${a.ids.length} questions<br><span style="opacity:.75">You can pause and return at any time.</span></p><button class="pill" ${slot?'':'id="grade"'} data-grade data-action="grade" ${chosen<a.ids.length?'disabled':''}>${isDeep?'View results & self-assessment':'Grade '+a.ids.length+' questions'} ↗</button></div></div>${slot?'':'</div>'}`;}
function quizSourceContext(q){
 const norm=s=>s.replace(/\s+/g,' ').trim().toLowerCase();
 const section=data.lessons.find(l=>l.id===q.lesson)?.sections.find(s=>s.english.blocks.some(b=>b.pdfPage===q.audit.pdfPage&&norm(b.text).includes(norm(q.audit.evidence))));
 return section?`<details><summary>Read the supporting DMV source</summary>${section.english.blocks.map(b=>`<h3>${e(b.heading)}</h3>${englishParagraphs(b.text)}`).join('')}</details>`:'';
}
function questionCard(q,n,a,result){
 const isDeep=a.mode==='deep',value=result?result.choice:a.choices[q.id],correct=result?.correct;
 let options;
 if(isDeep&&q.type==='short')options=result?`<p><b>Your response:</b></p><p class="student-response" style="white-space:pre-wrap">${e(value)}</p>`:`<label class="form-note" for="answer-${q.id}">Explain your decision and the conditions you need to check.</label><textarea id="answer-${q.id}" class="notes" lang="en" maxlength="20000" data-answer="${q.id}">${e(value||'')}</textarea>`;
 else {
  const list=isDeep?q.options:q.answers.map(x=>x.text);
  options=list.map((text,i)=>{const val=isDeep?i:String(q.answers[i].value),selected=q.type==='multi'&&isDeep?Array.isArray(value)&&value.includes(i):value===val;
   const right=result&&(isDeep?(q.type==='multi'?q.correct.includes(i):q.correct===i):q.correct===val);
   return `<label class="option ${result&&right?'correct-option':result&&selected&&!right?'wrong-option':''}"><input ${result?'disabled':''} type="${isDeep&&q.type==='multi'?'checkbox':'radio'}" name="q-${q.id}" data-answer="${q.id}" value="${val}" ${selected?'checked':''}><span class="letter">${letters[i]||i+1}</span><span>${e(text)}</span></label>`;
  }).join('');
 }
 const page=isDeep?q.pdfPage:q.audit.pdfPage;
 return `<fieldset class="question" lang="en"><legend><span class="question-number">QUESTION ${n} ${isDeep?'· '+(q.type==='multi'?'SELECT ALL CORRECT ANSWERS':q.type==='short'?'WRITTEN RESPONSE · SELF-ASSESSMENT':'SELECT ONE ANSWER'):'· DMV #'+q.id}${result?' · '+(correct===null?'Self-assessment':correct?'✓ Correct':'Review needed'):''}</span>${e(isDeep?q.prompt:q.question)}</legend><div class="question-body">${(q.images||[]).map(path=>`<img src="/${e(path)}" alt="Original DMV illustration for question ${n}" loading="lazy">`).join('')}${options}${result?`<div class="feedback"><p><b>${isDeep?'Explanation based on DMV rules':'Official DMV explanation'}</b></p><p>${e(isDeep?q.explanation:q.feedback)}</p>${isDeep&&q.rubric?`<p><b>Self-assessment checklist:</b></p><ul class="rubric">${q.rubric.map(x=>`<li>${e(x)}</li>`).join('')}</ul><p class="form-note">Your written response is saved for review and is not automatically scored as correct or incorrect.</p>`:''}<p><a href="${pdf(page)}" target="_blank" rel="noopener">Virginia DMV · printed page ${page-2} ↗</a></p>${!isDeep?`${quizSourceContext(q)}<a href="${e(q.source_url)}" target="_blank" rel="noopener">Open this question in the DMV Study Guide ↗</a>`:''}</div>`:''}</div></fieldset>`;
}
function resultsPage(session=state,slot=null){const a=session.last,pool=a.mode==='deep'?data.deep:data.questions,isDeep=a.mode==='deep',self=a.results.filter(r=>r.correct===null).length,pass=a.mode==='exam'&&(a.stage==='signs'?a.score===10:a.score>=24),mistakes=a.results.filter(r=>r.correct===false);return `${slot?'':'<div class="wrap">'}<div class="quiz-shell" lang="en" ${slot?`data-quiz-slot="${e(slot)}"`:''}><p class="eyebrow">RESULTS SAVED · ${isDeep?'TUTOR-WRITTEN EXERCISES':'DMV QUESTIONS'}</p><div class="result-hero"><div><${slot?'h3':'h1'} style="font-size:29px">${a.mode==='exam'?(pass?'Passed: '+(a.stage==='signs'?'traffic signs':'general knowledge'):'This section needs more review'):'Learn from every attempt.'}</${slot?'h3':'h1'}><p>${a.total?'Score for questions with fixed answers.':'Written responses: review the model answer and assess your reasoning.'}${self?' '+self+' written response(s) saved separately and not automatically scored.':''}</p></div><strong class="score">${a.total?a.score+'/'+a.total:'✓'}</strong></div>${mistakes.length?`<section class="panel"><h2>Mistakes to review</h2>${mistakes.map(r=>{const q=pool.find(q=>q.id===r.id);return `<div class="pitfall"><p>${e(isDeep?q.prompt:q.question)}</p><p>${e(isDeep?q.explanation:q.feedback)}</p></div>`;}).join('')}</section>`:''}<section class="panel"><h2>Question-by-question results</h2>${a.results.map((r,i)=>`<div class="result-row"><span>Question ${i+1}</span><span>${isDeep&&deepById(r.id).type==='short'?'Written response':isDeep&&deepById(r.id).type==='multi'?r.choice.map(n=>letters[n]).join(', '):isDeep?letters[r.choice]:letter(r.choice)}</span><span class="${r.correct===false?'bad':'good'}">${r.correct===null?'Self-assessment':r.correct?'Correct':'Review needed'}</span></div>`).join('')}</section>${a.results.map((r,i)=>questionCard(pool.find(q=>q.id===r.id),i+1,a,r)).join('')}<div class="button-row">${!slot&&a.reviewFor?`<a class="pill" href="/lessons/${e(a.reviewFor)}/">Continue to the new lesson →</a>`:''}${slot?'':a.mode==='exam'&&a.stage==='signs'&&pass?button('Open Part 2 · 30 questions →','exam-next'):button(isDeep?'Choose another exercise set':'Choose another practice set','new-session')}<a class="pill light" href="/progress/">View progress</a></div><p class="form-note">${a.mode==='exam'?'Practice results do not guarantee an actual exam result.':'Missed questions are saved for review. You can revisit the lesson before starting another set.'}</p></div>${slot?'':'</div>'}`;}
function progress(){const wrong=wrongIds(),due=dueIds(),attempts=allAttempts(),acc=attempts?Math.round(Object.values(state.answers).reduce((n,a)=>n+a.correct,0)/attempts*100):0;return `<div class="wrap">${title('TIẾN ĐỘ & SỔ LỖI','Nhìn rõ mình đã hiểu đến đâu.','Lý thuyết đã đọc, câu DMV đã làm và bài tập hiểu sâu được theo dõi riêng. Bản lưu thuộc trình duyệt và địa chỉ website này.')}<div class="stats"><div class="stat"><strong>${Object.keys(state.answers).length}</strong><span>câu DMV đã làm</span></div><div class="stat"><strong>${attempts?acc+'%':'—'}</strong><span>đúng / ${attempts} lượt</span></div><div class="stat"><strong>${wrong.length}</strong><span>câu gần nhất sai</span></div><div class="stat"><strong>${Object.keys(state.deep).length}</strong><span>bài hiểu sâu đã làm</span></div></div>${state.checkpoint?`<div class="callout"><b>Điểm dừng đã lưu:</b> ${e(state.checkpoint)}</div>`:''}${state.active?activeBanner('official'):''}<div class="review-grid"><section class="panel"><h2>Ôn lại đúng lúc</h2><p>${due.length} câu đã đến lịch ôn. Đúng 1, 2, 3, 4 lần liên tiếp được hẹn sau 1, 3, 7, 14 ngày. Sai thì cần ôn từ hôm nay.</p><div class="button-row">${button('Ôn câu đến hạn','start-due')}${button('Ôn câu sai','start-wrong')}</div>${wrong.length?`<div style="margin-top:20px">${wrong.map(id=>`<div class="result-row"><a href="/lessons/${byId(id).lesson}/">#${id} · ${e(byId(id).question)}</a></div>`).join('')}</div>`:'<p class="form-note">Sổ lỗi sẽ xuất hiện sau khi có câu trả lời sai.</p>'}</section><section class="panel"><h2>Sao lưu & chuyển thiết bị</h2><p>Xuất tệp sau một buổi học. Khi đổi trình duyệt hoặc máy, nhập lại tệp để học tiếp. Xóa dữ liệu trình duyệt sẽ xóa bản lưu tại đây.</p><div class="button-row">${button('Xuất tiến độ JSON ↓','export')}</div><label class="form-note" for="import-progress" style="margin:20px 0 10px">Nhập tiến độ web hoặc progress.json từ agent cũ (sẽ xem trước khi áp dụng).</label><input id="import-progress" class="file-input" type="file" accept="application/json,.json"><div id="import-preview"></div><p class="form-note">Tệp được đọc trên máy, không gửi lên máy chủ. Trước khi nhập, website giữ một bản sao lưu của tiến độ hiện tại.</p>${button('Khôi phục bản lưu trước','restore','class="pill light"')}</section></div><section class="panel"><h2>Theo từng bài</h2><div class="table-wrap"><table><thead><tr><th>BÀI HỌC</th><th>ĐÃ ĐỌC</th><th>CÂU DMV ĐÃ LÀM</th><th>GẦN NHẤT ĐÚNG</th><th>HIỂU SÂU</th></tr></thead><tbody>${data.lessons.map(l=>{const qs=eligible().filter(q=>q.lesson===l.id),done=qs.filter(q=>state.answers[q.id]);return `<tr><td><a href="/lessons/${l.id}/">${l.id.slice(1)} · ${e(l.title)}</a></td><td>${countRead(l)}/${l.sections.length}</td><td>${done.length}/${qs.length}</td><td>${done.filter(q=>state.answers[q.id].last_correct).length}/${done.length}</td><td>${data.deep.filter(q=>q.lesson===l.id&&state.deep[q.id]).length}/${data.deep.filter(q=>q.lesson===l.id).length}</td></tr>`;}).join('')}</tbody></table></div></section></div>`;}
function sources(){const holds=data.questions.filter(q=>q.audit.status!=='verified');return `<div class="wrap">${title('TÀI LIỆU & TÍNH MINH BẠCH','Biết rõ mình đang học từ đâu.','Website học cá nhân từ nguồn Virginia DMV. Phần diễn giải tiếng Việt và bài tập hiểu sâu do gia sư biên soạn; không phải bản dịch hay đề thi chính thức.')}<div class="review-grid"><section class="panel"><h2>Nguồn chính thức</h2><ul><li><a href="https://www.dmv.virginia.gov/licenses-ids/exams/manual" target="_blank" rel="noopener">Trang Virginia DMV Driver’s Manual ↗</a></li><li><a href="${pdf(1)}" target="_blank" rel="noopener">Sổ tay PDF tháng 4/2026 ↗</a></li><li><a href="https://transactions.dmv.virginia.gov/dmv-manuals/" target="_blank" rel="noopener">Study Guide và câu luyện tập công khai ↗</a></li><li><a href="https://www.dmv.virginia.gov/licenses-ids/exams/know-exam" target="_blank" rel="noopener">Thể thức kỳ thi kiến thức ↗</a></li></ul><p>Dữ liệu gốc tải ngày 15/09/2026. Trang DMV và tên bản PDF được kiểm tra lại ngày 27/10/2026. Đây là bộ học theo bản lưu, không tự cập nhật khi DMV sửa tài liệu.</p><p>Với thủ tục và thông tin có thể thay đổi, mở lại trang DMV trước khi sử dụng. Một số nội dung nguồn có dấu hiệu không đồng nhất; mục đó được ghi chú trong bài học.</p></section><section class="panel"><h2>Ba loại nội dung</h2><ul><li><b>Lý thuyết:</b> diễn giải tiếng Việt, có trang PDF và hình gốc để đối chiếu đầy đủ.</li><li><b>Ôn thi DMV:</b> ${data.questions.length} câu gốc được giữ nguyên tiếng Anh và lựa chọn. Chỉ ${eligible().length} câu đủ căn cứ đối chiếu được dùng để chấm.</li><li><b>Hiểu sâu:</b> ${data.deep.length} bài do gia sư biên soạn từ các quy tắc DMV; kết quả được lưu riêng.</li></ul><p>Rà ý nghĩa và kiểm tra phần mềm giúp giảm lỗi; không phải chứng nhận của DMV hay bảo đảm đỗ kỳ thi.</p></section></div><section class="panel"><h2>${holds.length} câu đang giữ lại</h2><p>Câu có nội dung chưa rõ hoặc mâu thuẫn sẽ không được chọn vào gói ôn hay đề mô phỏng. Tiếng Anh nguyên gốc vẫn được lưu để tra cứu.</p><div class="table-wrap"><table><thead><tr><th>MÃ CÂU</th><th>BÀI</th><th>LÝ DO</th><th>ĐỐI CHIẾU</th></tr></thead><tbody>${holds.map(q=>`<tr><td>#${q.id}</td><td>${q.lesson}</td><td>${e(q.audit.reason)}</td><td>${src(q.audit.pdfPage)}</td></tr>`).join('')}</tbody></table></div></section></div>`;}
function notFound(){return '<div class="wrap"><div class="empty"><h1>Trang này chưa có.</h1><a class="pill" href="/">Về trang chủ</a></div></div>';}
function render(){let path=location.pathname.replace(/\/+$/,'')||'/',html;const mode=path==='/deep'?'deep':'official';if(path==='/')html=hub();else if(path==='/driving')html=home();else if(path==='/english')html=english();else if(path==='/cinema')html=cinema();else if(path==='/lessons')html=lessons();else if(/^\/lessons\/L\d\d$/.test(path)){const id=path.split('/').at(-1);prepareLessonSessions(id);html=lessonPage(id);}else if(path==='/practice'||path==='/deep'){const matching=state.active&&(mode==='deep'?state.active.mode==='deep':state.active.mode!=='deep'),last=state.last&&(mode==='deep'?state.last.mode==='deep':state.last.mode!=='deep');html=matching?activeQuiz():last?resultsPage():quizLanding(mode);}else if(path==='/progress')html=progress();else if(path==='/sources')html=sources();else html=notFound();main.innerHTML=html;document.title=path.startsWith('/lessons/L')?(data.lessons.find(l=>l.id===path.split('/').at(-1))?.title||'Bài học')+' · Virginia Driving':({'/':'PHT Learning Hub','/driving':'Học lái xe Virginia','/english':'Học tiếng Anh','/cinema':'Cẩm nang điện ảnh','/practice':'Ôn thi DMV','/deep':'Hiểu sâu','/progress':'Tiến độ','/sources':'Nguồn DMV','/lessons':'16 bài học'}[path]||'PHT Learning Hub')+' · PHT Learning Hub';document.querySelectorAll('nav a').forEach(a=>{const on=path.startsWith(new URL(a.href).pathname.replace(/\/$/,''));a.classList.toggle('active',on);if(on)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});}
let importCandidate=null;
document.addEventListener('click',ev=>{const a=ev.target.closest('a');if(a&&a.origin===location.origin&&!a.hasAttribute('download')&&!a.hasAttribute('data-document')&&!a.target&&!ev.metaKey&&!ev.ctrlKey&&!ev.shiftKey&&ev.button===0){ev.preventDefault();if(a.hash&&a.pathname===location.pathname){document.getElementById(a.hash.slice(1))?.scrollIntoView();return;}nav(a.pathname+a.search+a.hash);return;}const b=ev.target.closest('[data-action]');if(!b)return;const act=b.dataset.action;
 if(act==='lesson-next'){
  const {slot}=quizSession(b);if(!slot)return;const [id,kind]=slot.split(':');
  if(update(s=>{const session=s.lessonSessions[slot];session.size=Number(b.closest('[data-quiz-slot]').querySelector('[data-lesson-size]').value);session.active=lessonBatch(id,kind,session.size);session.last=null;})){render();scrollQuiz(slot);}
 }
 else if(act==='start-official'||act==='start-deep')start(act==='start-deep'?'deep':'official');
 else if(act==='start-due'||act==='start-wrong')start('official',act==='start-due'?'due':'wrong');
 else if(act==='start-exam')startExam();
 else if(act==='read'){const id=b.dataset.lesson,i=Number(b.dataset.index);if(update(s=>{const list=s.read[id]||[];s.read[id]=list.includes(i)?list.filter(n=>n!==i):[...list,i];s.current=id;s.checkpoint='Bài '+id.slice(1)+' · '+data.lessons.find(l=>l.id===id).sections[i].title;})){const on=state.read[id].includes(i);b.setAttribute('aria-pressed',String(on));b.textContent=on?'✓ Đã đọc phần này':'Đánh dấu đã đọc';notice(on?'Đã lưu mục vừa đọc.':'Đã bỏ đánh dấu mục này.');}}
 else if(act==='zoom'){const p=String(b.dataset.page).padStart(2,'0');$('#image-dialog img').src=`/assets/visuals/page-${p}.png`;$('#image-dialog img').alt='Trang in '+(Number(p)-2)+' của sổ tay DMV';$('#image-dialog').showModal();}
 else if(act==='grade'){try{const {slot}=quizSession(b);if(write(finish(state,data.questions,data.deep,new Date(),slot))){render();scrollQuiz(slot);notice('Results saved.');}}catch(err){notice(err.message);}}
 else if(act==='page-next'||act==='page-prev'){quizPage+=act==='page-next'?1:-1;render();window.scrollTo(0,0);}
 else if(act==='new-session'){if(update(s=>s.last=null)){render();window.scrollTo(0,0);}}
 else if(act==='exam-next'){const last=state.last;if(last?.mode==='exam'&&last.stage==='signs'&&last.score===10&&update(s=>{s.active={token:crypto.randomUUID(),mode:'exam',stage:'general',ids:last.general,general:last.general,signScore:last.score,choices:{},created:new Date().toISOString()};s.last=null;})){quizPage=0;render();window.scrollTo(0,0);}}
 else if(act==='export')download(state,'virginia-progress-'+today()+'.json');
 else if(act==='apply-import'&&importCandidate){if(write(importCandidate)){importCandidate=null;render();notice('Đã nhập tiến độ. Có thể tiếp tục học.');}}
 else if(act==='restore'){try{const raw=localStorage.getItem(KEY+'-backup');if(!raw)throw Error('Chưa có bản sao lưu trước.');const recovered=validate(JSON.parse(raw),data.questions,data.deep);storageError=false;if(write(recovered)){render();notice('Đã khôi phục bản lưu trước.');}}catch(err){notice(err.message);}}
});
document.addEventListener('change',async ev=>{const el=ev.target;if(el.id==='import-progress'){try{const f=el.files[0];if(!f)return;if(f.size>5e6)throw Error('Tệp lớn hơn 5 MB; hãy chọn tệp tiến độ JSON.');importCandidate=validate(JSON.parse(await f.text()),data.questions,data.deep);$('#import-preview').innerHTML=`<div class="callout" style="margin-top:15px">Tệp hợp lệ: ${Object.keys(importCandidate.answers).length} câu DMV đã làm, ${importCandidate.history.length} lượt trong lịch sử. Nhập sẽ thay bản lưu hiện tại; bản trước được sao lưu.<div class="button-row">${button('Áp dụng bản tiến độ này','apply-import')}</div></div>`;}catch(err){importCandidate=null;$('#import-preview').textContent=err.message;}return;}
 if(el.dataset.answer&&el.tagName!=='TEXTAREA'){const id=el.dataset.answer,{slot,session}=quizSession(el),a=session?.active;if(!a)return;let value=el.value;if(a.mode==='deep'){const q=deepById(id);value=q.type==='multi'?[...document.querySelectorAll(`input[data-answer="${id}"]:checked`)].map(x=>Number(x.value)):Number(value);}if(!update(s=>(slot?s.lessonSessions[slot]:s).active.choices[id]=value)){render();return;}refreshCount(slot);}
});
function refreshCount(slot=null){const root=slot?document.querySelector(`[data-quiz-slot="${slot}"]`):main,a=(slot?state.lessonSessions[slot]:state).active;if(!a)return;const pool=a.mode==='deep'?data.deep:data.questions,n=a.ids.filter(id=>answered(pool.find(q=>q.id===id),a.choices[id],a.mode)).length;root.querySelector('[data-quiz-count]').innerHTML=`Answered ${n}/${a.ids.length} questions<br><span style="opacity:.75">Your answers are saved in this browser.</span>`;root.querySelector('[data-grade]').disabled=n<a.ids.length;}
document.addEventListener('input',ev=>{const el=ev.target;if(el.id==='lesson-search'){search=el.value;$('#lesson-list').innerHTML=lessonCards();}else if(el.id==='lesson-note'){if(update(s=>s.notes[el.dataset.lesson]=el.value))$('#notes-status').textContent='Đã lưu ghi chú.';}else if(el.tagName==='TEXTAREA'&&el.dataset.answer&&state.active){if(update(s=>s.active.choices[el.dataset.answer]=el.value))refreshCount();}});
window.addEventListener('popstate',()=>{quizPage=0;render();});
$('#image-dialog .dialog-close').addEventListener('click',()=>$('#image-dialog').close());
try{const response=await fetch('/data/course.json');if(!response.ok)throw Error('Không tải được dữ liệu bài học.');data=await response.json();const raw=localStorage.getItem(KEY);if(raw){try{state=validate(JSON.parse(raw),data.questions,data.deep);}catch{storageError=true;main.innerHTML='<div class="wrap"><div class="callout error"><h1 style="font-size:25px">Bản lưu cần được kiểm tra.</h1><p>Dữ liệu gốc được giữ nguyên. Hãy tải bản lưu để sao lưu trước khi thử khôi phục.</p><button class="pill" id="raw-export">Tải bản lưu gốc ↓</button> <button class="pill light" data-action="restore">Khôi phục bản trước</button></div></div>';$('#raw-export').onclick=()=>download(raw,'virginia-progress-original.json');state=fresh();throw Error('CORRUPT_STATE');}}else state=fresh();render();}catch(err){if(err.message!=='CORRUPT_STATE')main.innerHTML=`<div class="wrap"><div class="callout error"><h1 style="font-size:25px">Chưa mở được bộ học.</h1><p>${e(err.message)} Hãy tải lại trang khi có kết nối.</p><button class="pill" onclick="location.reload()">Tải lại trang</button></div></div>`;}
